private static void ApplyPhachPrintSafeZone(DevExpress.XtraRichEdit.RichEditControl editor)
{
    if (editor == null || editor.Document == null)
        return;

    DevExpress.XtraRichEdit.API.Native.Document document = editor.Document;
    DevExpress.XtraRichEdit.API.Native.DocumentRange[] ranges = document.FindAll("ĐỀ SỐ", DevExpress.XtraRichEdit.API.Native.SearchOptions.None);
    if (ranges == null || ranges.Length == 0)
        return;

    for (int i = 0; i < ranges.Length; i++)
    {
        DevExpress.XtraRichEdit.API.Native.DocumentRange findRange = ranges[i];
        DevExpress.XtraRichEdit.API.Native.Paragraph targetParagraph = null;

        for (int p = 0; p < document.Paragraphs.Count; p++)
        {
            DevExpress.XtraRichEdit.API.Native.Paragraph paragraph = document.Paragraphs[p];
            if (paragraph.Range.Start.ToInt() <= findRange.Start.ToInt()
                && paragraph.Range.End.ToInt() >= findRange.End.ToInt())
            {
                targetParagraph = paragraph;
                break;
            }
        }

        if (targetParagraph == null)
            continue;

        DevExpress.XtraRichEdit.API.Native.ParagraphProperties props = document.BeginUpdateParagraphs(targetParagraph.Range);
        props.SpacingBefore = 0.8f;
        document.EndUpdateParagraphs(props);
    }
}

