/// <summary>
/// Chèn ảnh trống vào vùng header để lấp khoảng chừa khi qua trang.
/// </summary>
private static void AddPhachBlankImageToHeader(DevExpress.XtraRichEdit.RichEditControl editor)
{
    if (editor == null || editor.Document == null)
        return;

    string imageFilePath = Application.StartupPath + "\\Template\\anhtrong.jpg";
    if (!System.IO.File.Exists(imageFilePath))
        return;

    for (int sectionIndex = 0; sectionIndex < editor.Document.Sections.Count; sectionIndex++)
    {
        DevExpress.XtraRichEdit.API.Native.Section section = editor.Document.Sections[sectionIndex];
        DevExpress.XtraRichEdit.API.Native.SubDocument header = section.BeginUpdateHeader();
        editor.Document.Images.Insert(header.Range.Start, DevExpress.XtraRichEdit.API.Native.DocumentImageSource.FromFile(imageFilePath));
        section.EndUpdateHeader(header);
    }
}

