/// <summary>
/// Chèn ảnh Template/anhtrong.jpg vào header từ trang 2 trở đi (trang 1 không hiện).
/// </summary>
private static void AddPhachBlankImageToHeader(DevExpress.XtraRichEdit.RichEditControl editor)
{
    if (editor == null || editor.Document == null)
        return;

    string imageFilePath = Application.StartupPath + "\\Template\\anhtrong.jpg";
    if (!System.IO.File.Exists(imageFilePath))
        return;

    for (int sectionIndex = 0; sectionIndex < editor.Document.Sections.Count; sectionIndex++)
    {
        DevExpress.XtraRichEdit.API.Native.Section section = editor.Document.Sections[sectionIndex];
        section.DifferentFirstPage = true;

        // Trang 1: header riêng, để trống
        DevExpress.XtraRichEdit.API.Native.SubDocument firstHeader = section.BeginUpdateHeader(
            DevExpress.XtraRichEdit.API.Native.HeaderFooterType.First);
        if (firstHeader.Range.Length > 0)
            firstHeader.Delete(firstHeader.Range);
        section.EndUpdateHeader(firstHeader);

        // Từ trang 2: chèn ảnh vào header chính
        DevExpress.XtraRichEdit.API.Native.SubDocument header = section.BeginUpdateHeader(
            DevExpress.XtraRichEdit.API.Native.HeaderFooterType.Primary);
        DevExpress.XtraRichEdit.API.Native.Shape picture = header.Shapes.InsertPicture(
            header.Range.Start,
            DevExpress.XtraRichEdit.API.Native.DocumentImageSource.FromFile(imageFilePath));
        if (picture != null)
        {
            picture.VerticalAlignment = DevExpress.XtraRichEdit.API.Native.ShapeVerticalAlignment.Top;
            picture.HorizontalAlignment = DevExpress.XtraRichEdit.API.Native.ShapeHorizontalAlignment.Left;
        }
        section.EndUpdateHeader(header);
    }
}
